2. Exploratory Questions

Question 1: What date range is covered by the dataset?


Show Code
date_range&lt;-NETFLIX_DATA|&gt;
  summarise(Start=min(period_start),
            End=max(period_end))
start_date &lt;- date_range |&gt; pull(Start)
end_date &lt;- date_range |&gt; pull(End)


The data set covers from 2023-01-01 to 2026-07-30.


Question 2: How many different shows and movies are covered in this data set?


Show Code
total_titles&lt;-NETFLIX_DATA|&gt;
  summarise(number_titles=comma(n_distinct(title,na.rm=TRUE)))|&gt;
  pull(number_titles)


The dataset contains 24,427 different shows and movies.


Question 3: How many total hours have been spent watching shows from the Bridgerton universe?


Show Code
total_bridge_hours&lt;-NETFLIX_DATA|&gt;
  filter(str_detect(title,"Bridgerton"))|&gt;
  summarise(total_hours=comma(sum(hours_viewed,na.rm=TRUE)))


4,862,800,000 hours has been spent watching shows from the Bridgerton universe.


Question 4: How many total hours have been spent watching the five seasons of Stranger Things?
To get the total viewing hours of the five seasons of Stranger Things, I exclude any related spin-offs. This allows us to focus on viewership of the main series.


Show Code
total_strange_hours&lt;-NETFLIX_DATA|&gt;
  filter(str_detect(title,"Stranger Things"))|&gt;
  filter_out(str_detect(title,"Beyond"))|&gt;
  filter_out(str_detect(title,"Fireplace"))|&gt;
  filter_out(str_detect(title,"Tales"))|&gt;
  summarise(total_hours=comma(sum(hours_viewed,na.rm=TRUE)))|&gt;
  pull(total_hours)


Across the seven periods, we get that a total of 5,548,500,000 hours has been spent watching the five seasons of Stranger Things.


Question 5: What percentage of total watch time was spent on the Top 10 titles of 2026H1?


Show Code
total&lt;-NETFLIX_DATA|&gt;
  filter(period=='2026H1')|&gt;
  summarise(total_hours=sum(hours_viewed,na.rm=TRUE))|&gt;
  pull(total_hours)

percent_of_total&lt;-NETFLIX_DATA|&gt;
  filter(period=='2026H1')|&gt;
  slice_max(hours_viewed,n=10)|&gt;
  summarise(percentage=percent(sum(hours_viewed)/total, accuracy=.001))|&gt;
  pull(percentage)


6.697% of total watch time in 2026H1 was spent on the Top 10 titles.


Question 6: What fraction of Netflix’s catalog is globally available?


Show Code
Total&lt;-NETFLIX_DATA|&gt;
  summarise(total_hours=sum(hours_viewed,na.rm=TRUE))|&gt;
  pull(total_hours)

global_hours_percentage&lt;-NETFLIX_DATA|&gt;
  filter(available_globally=='TRUE')|&gt;
  summarise(hours_percentage=percent(sum(hours_viewed)/Total,accuracy=.01))|&gt;
  pull(hours_percentage)


total_distinct&lt;-NETFLIX_DATA|&gt;
  summarise(total_titles=n_distinct(title,na.rm=TRUE))|&gt;
  pull(total_titles)


global_titles_percentage&lt;-NETFLIX_DATA|&gt;
  filter(available_globally=='TRUE')|&gt;
  summarise(percentage_distinct=percent(n_distinct(title)/total_distinct,accuracy=.01))|&gt;
  pull(percentage_distinct)


Globally available titles account for 51.92% of Netflix’s total viewing hours and 24.60% of its unique titles.

Supporting Calculations for Executive Memo


Show Supporting Calculations
top_15_titles &lt;- NETFLIX_DATA |&gt;
  group_by(title) |&gt;
  filter(n_distinct(period) == 7) |&gt;
  summarise(
    average_hours = mean(hours_viewed, na.rm = TRUE),
    sd_hours = sd(hours_viewed, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  mutate(
    cv = sd_hours / average_hours
  )|&gt;
  slice_max(average_hours,n=15)

night_agent_avg &lt;- top_15_titles |&gt;
  filter(title == "The Night Agent: Season 1") |&gt;
  pull(average_hours)

night_agent_cv &lt;- top_15_titles |&gt;
  filter(title == "The Night Agent: Season 1") |&gt;
  pull(cv)

pablo_avg &lt;- top_15_titles |&gt;
  filter(str_detect(title, "Pablo Escobar"))|&gt;
  pull(average_hours)

pablo_cv &lt;- top_15_titles |&gt;
  filter(str_detect(title, "Pablo Escobar"))|&gt;
  pull(cv)

viewing_summary&lt;- NETFLIX_CLASSIFIED |&gt;
  group_by(period, content_type) |&gt;
  summarise(
    total_hours = sum(hours_viewed, na.rm = TRUE),
    .groups = "drop")|&gt;
  group_by(period)|&gt;
  mutate(
    proportion = total_hours / sum(total_hours))|&gt;
  ungroup()|&gt;
  filter(content_type != "Unknown")

show_percentage &lt;- viewing_summary |&gt;
  filter(period == "2026H1", content_type == "Show") |&gt;
  pull(proportion)

movie_percentage &lt;- viewing_summary |&gt;
  filter(period == "2026H1", content_type == "Movie") |&gt;
  pull(proportion)



live_summary&lt;- NETFLIX_DATA |&gt;
  filter(!is.na(views)) |&gt;
  group_by(live_event) |&gt;
  summarise(
    average_views = mean(views, na.rm = TRUE),
    number_titles = n_distinct(title),
    .groups = "drop"
  ) 
live_avg &lt;- live_summary |&gt;
  filter(live_event == TRUE) |&gt;
  pull(average_views)

prerecorded_avg &lt;- live_summary |&gt;
  filter(live_event == FALSE) |&gt;
  pull(average_views)
